func _codex_ai_chest_states(limit: int) -> Array:
	var entries := []
	for chest in collectibles:
		if not is_instance_valid(chest):
			continue
		entries.append({
			"id": _node_id(chest),
			"x": chest.global_position.x,
			"y": chest.global_position.y,
			"distance": player.global_position.distance_to(chest.global_position),
			"opened": bool(chest.get_meta("opened", false)),
			"kind": String(chest.get_meta("kind", "coin"))
		})
	entries.sort_custom(_sort_distance_entries)
	return entries.slice(0, mini(limit, entries.size()))


